// 營利事業所得稅查核準則 §88(2)(1): up to NT$3,000 a month is not salary income; this row stays out of SALARY_INCOME.
// 勞工請假規則 §7: no wage for a no-pay day, so the exempt meal falls and returns with BASIC_AFTER_UNPAID_LEAVE and the days stay out of SALARY_INCOME.
const basic = ctx.subtotals.BASIC;
const taken = ctx.subtotals.BASIC_AFTER_PARENTAL_LEAVE - ctx.subtotals.BASIC_AFTER_UNPAID_LEAVE;
const left = basic > 0 ? Math.max(0, 1 - taken / basic) : 1;
return Math.min(Number(get(ctx.subject.employment.terms, 'allowances.MEAL_ALLOWANCE.amount', 0)), ctx.lookup.meal_exempt_monthly) * left;

// 勞工請假規則 §7: no wage for a no-pay day; the part above the exempt meal falls and returns with BASIC_AFTER_UNPAID_LEAVE.
const basic = ctx.subtotals.BASIC;
const taken = ctx.subtotals.BASIC_AFTER_PARENTAL_LEAVE - ctx.subtotals.BASIC_AFTER_UNPAID_LEAVE;
const left = basic > 0 ? Math.max(0, 1 - taken / basic) : 1;
return (Number(get(ctx.subject.employment.terms, 'allowances.MEAL_ALLOWANCE.amount', 0)) - ctx.lookup.meal_exempt_monthly) * left;
